-- Full rollback regression. Only synthetic IDs are used; ordinary business rows
-- are not changed. Run on the authorized test project after the migration.
do $test$
#variable_conflict use_variable
declare
 company uuid:='d1200000-0000-4000-8000-000000000001'; foreign_company uuid:='d1200000-0000-4000-8000-000000000002';
 actor uuid:='d1200000-0000-4000-8000-000000000003'; user_id uuid:='d1200000-0000-4000-8000-000000000004';
 customer uuid:='d1200000-0000-4000-8000-000000000005'; portal_user uuid:='d1200000-0000-4000-8000-000000000006';
 worker uuid:='d1200000-0000-4000-8000-000000000007'; worker_user uuid:='d1200000-0000-4000-8000-000000000008';
 calc_id uuid; quote_id uuid; version_a uuid;version_b uuid;job_id uuid;
 operation uuid:=gen_random_uuid(); publish_op uuid:=gen_random_uuid(); conversion_op uuid:=gen_random_uuid();
 decision_op uuid:=gen_random_uuid(); response_op uuid:=gen_random_uuid(); delivery_op uuid:=gen_random_uuid();
 input jsonb; data jsonb; public_input jsonb; public_first jsonb; response jsonb; previous jsonb; document_a jsonb; workspace jsonb; snapshot jsonb; plan jsonb;
 token_a text;token_b text;attempt text;delivery_id uuid; count_before integer; tests text[]:='{}'; cleanup integer:=0;
begin
 if exists(select 1 from public.companies where id in(company,foreign_company)) or exists(select 1 from auth.users where id in(user_id,portal_user,worker_user)) then raise exception 'TEST_FIXTURE_COLLISION';end if;
 begin
  insert into auth.users(id,email,raw_user_meta_data) values(user_id,'quote-lifecycle@example.invalid','{}'),(portal_user,'quote-portal@example.invalid','{}'),(worker_user,'quote-worker@example.invalid','{}');
  insert into public.companies(id,name) values(company,'TEST quote lifecycle'),(foreign_company,'TEST foreign quote lifecycle');
  insert into public.profiles(id,auth_user_id,user_id,full_name,is_active) values(actor,user_id,user_id,'TEST quote owner',true),(worker,worker_user,worker_user,'TEST quote worker',true);
  insert into public.company_members(company_id,profile_id,role,is_active) values(company,actor,'company_admin',true),(company,worker,'worker',true);
  insert into public.customers(id,company_id,name,billing_street,email) values(customer,company,'TEST original customer','Original street 1','customer@example.invalid');
  insert into public.customer_portal_users(company_id,customer_id,auth_user_id,email,is_active) values(company,customer,portal_user,'quote-portal@example.invalid',true);
  perform set_config('request.jwt.claim.sub',user_id::text,true);
  input:=jsonb_build_object('customer_id',customer,'title','TEST source calculation','description',null,'status','draft','calculation_date','2026-10-21','internal_note','Internal only','currency','CZK',
   'items',jsonb_build_array(jsonb_build_object('item_type','customer','name','Customer zero','description',null,'quantity','1.00','unit','ks','unit_cost','0.00','unit_price','0.00','vat_rate','0.00','note',null),
     jsonb_build_object('item_type','material','name','Internal cost','description',null,'quantity','1.00','unit','ks','unit_cost','1.00','unit_price','0.00','vat_rate','21.00','note','private cost')));
  execute 'set local role authenticated';
  response:=public.create_core_calculation_atomic(company,gen_random_uuid(),input);calc_id:=(response->>'calculationId')::uuid;
  response:=public.create_core_quote_from_calculation_atomic(company,calc_id,1,operation);quote_id:=(response->>'quoteId')::uuid;
  if response->>'revision'<>'1' or(response->>'replayed')::boolean then raise exception 'create_receipt';end if;tests:=array_append(tests,'create_receipt');
  workspace:=public.get_core_quote_workspace(company,quote_id);
  if jsonb_array_length(workspace->'draft'->'items')<>1 or workspace->'draft'->'items'->0->>'unit_price'<>'0.00' or workspace->'draft'->'items'->0->>'vat_rate'<>'0.00' then raise exception 'zero_customer_retained_no_internal_cost';end if;tests:=array_append(tests,'zero_customer_retained_no_internal_cost');
  if workspace->>'sourceCalculationRevision'<>'1' or workspace->>'currentCalculationRevision'<>'1' or not(workspace->>'draftOpen')::boolean then raise exception 'source_revision';end if;tests:=array_append(tests,'source_revision');
  previous:=response;response:=public.create_core_quote_from_calculation_atomic(company,calc_id,1,operation);
  if response-'replayed'<>previous-'replayed' or not(response->>'replayed')::boolean then raise exception 'create_exact_retry';end if;tests:=array_append(tests,'create_exact_retry');
  begin perform public.create_core_quote_from_calculation_atomic(company,calc_id,1,gen_random_uuid());raise exception 'expected_source_claim';exception when sqlstate 'PT409' then if sqlerrm<>'CORE_QUOTE_OPERATION_CONFLICT' then raise;end if;end;tests:=array_append(tests,'source_claim');
  begin perform public.create_core_quote_from_calculation_atomic(company,calc_id,2,operation);raise exception 'expected_changed_operation';exception when sqlstate 'PT409' then if sqlerrm<>'CORE_QUOTE_OPERATION_CONFLICT' then raise;end if;end;tests:=array_append(tests,'changed_operation');
  begin perform public.get_core_quote_workspace(foreign_company,quote_id);raise exception 'expected_foreign';exception when insufficient_privilege then null;end;tests:=array_append(tests,'foreign_company_denied');
  begin update public.quotes set title='unsafe' where id=quote_id;raise exception 'expected_direct_update';exception when insufficient_privilege then null;end;tests:=array_append(tests,'direct_update_denied');
  begin delete from public.quote_items i where i.quote_id=quote_id;raise exception 'expected_direct_items';exception when insufficient_privilege then null;end;tests:=array_append(tests,'direct_items_denied');
  begin insert into public.quotes(company_id,title) values(company,'unsafe direct create');raise exception 'expected_direct_insert';exception when insufficient_privilege then null;end;tests:=array_append(tests,'direct_quote_insert_closed');
  begin insert into private.core_quote_write_permits values(company,quote_id,pg_current_xact_id());raise exception 'expected_private_permit';exception when insufficient_privilege then null;end;tests:=array_append(tests,'private_permit_unforgeable');
  begin delete from public.quotes where id=quote_id;raise exception 'expected_direct_delete';exception when insufficient_privilege then null;end;tests:=array_append(tests,'direct_quote_delete_closed');
  begin perform public.publish_core_quote_customer_identity(company,quote_id);raise exception 'expected_old_publish';exception when insufficient_privilege then null;end;tests:=array_append(tests,'old_publish_closed');
  plan:=jsonb_build_object('title','TEST job','description',null,'address',null,'start_at','2026-10-22T08:00:00Z','end_at','2026-10-23T18:00:00Z','split_days',jsonb_build_array(jsonb_build_object('label','Day 1','start_at','2026-10-22T08:00:00Z','end_at','2026-10-22T18:00:00Z')));
  begin perform public.convert_core_quote_to_job_atomic(company,quote_id,conversion_op,plan);raise exception 'expected_old_create';exception when sqlstate 'PT409' then if sqlerrm<>'CORE_QUOTE_VERSION_REQUIRED' then raise;end if;end;tests:=array_append(tests,'old_conversion_cannot_implicitly_accept');
  data:=workspace->'draft';
  begin perform public.update_core_quote_draft_atomic(company,quote_id,1,gen_random_uuid(),data-'customer_note');raise exception 'expected_missing_key';exception when sqlstate '22023' then null;end;tests:=array_append(tests,'missing_top_key');
  begin perform public.update_core_quote_draft_atomic(company,quote_id,1,gen_random_uuid(),jsonb_set(data,'{content}',(data->'content')-'intro_text'));raise exception 'expected_missing_content';exception when sqlstate '22023' then null;end;tests:=array_append(tests,'missing_content_key');
  begin perform public.update_core_quote_draft_atomic(company,quote_id,1,gen_random_uuid(),jsonb_set(data,'{items,0,quantity}','"1.001"'));raise exception 'expected_precision';exception when sqlstate '22023' then null;end;tests:=array_append(tests,'precision_rejected');
  begin perform public.update_core_quote_draft_atomic(company,quote_id,1,gen_random_uuid(),jsonb_set(data,'{currency}','"EUR"'));raise exception 'expected_currency';exception when sqlstate '22023' then if sqlerrm<>'CORE_QUOTE_CURRENCY_UNSUPPORTED' then raise;end if;end;tests:=array_append(tests,'no_currency_reinterpretation');
  begin perform public.update_core_quote_draft_atomic(company,quote_id,1,gen_random_uuid(),jsonb_set(data,'{items,0,vat_rate}','null'));raise exception 'expected_unknown_vat';exception when sqlstate '22023' then null;end;tests:=array_append(tests,'unknown_vat_not_defaulted');
  data:=jsonb_set(data,'{items,0,unit_price}','"10.00"');data:=jsonb_set(data,'{discount_amount}','"2.00"');data:=jsonb_set(data,'{internal_note}','"NEVER PUBLIC internal margin 999"');
  response:=public.update_core_quote_draft_atomic(company,quote_id,1,gen_random_uuid(),data);
  if response->>'revision'<>'2' then raise exception 'atomic_update_revision';end if;tests:=array_append(tests,'atomic_update_revision');
  begin perform public.update_core_quote_draft_atomic(company,quote_id,1,gen_random_uuid(),data);raise exception 'expected_stale';exception when sqlstate 'PT409' then if sqlerrm<>'CORE_QUOTE_REVISION_CONFLICT' then raise;end if;end;tests:=array_append(tests,'stale_revision_no_overwrite');
  previous:=public.get_core_quote_draft_document(company,quote_id,2);
  if previous->>'kind'<>'draft' or previous->'document'->>'total_price'<>'8.00' or previous->'document'->>'subtotal_price'<>'10.00' or previous::text like '%NEVER PUBLIC%' then raise exception 'draft_preview_totals_whitelist';end if;tests:=array_append(tests,'draft_preview_totals_whitelist');
  begin perform public.get_core_quote_draft_document(company,quote_id,1);raise exception 'expected_preview_revision';exception when sqlstate 'PT409' then null;end;tests:=array_append(tests,'draft_preview_revision');
  response:=public.publish_core_quote_version_atomic(company,quote_id,2,publish_op);version_a:=(response->>'versionId')::uuid;token_a:=response->>'shareToken';
  if response->>'revision'<>'3' or response->>'versionNumber'<>'1' or length(token_a)<>64 then raise exception 'publication_receipt';end if;tests:=array_append(tests,'publication_receipt');
  previous:=response;response:=public.publish_core_quote_version_atomic(company,quote_id,2,publish_op);
  if response-'replayed'<>previous-'replayed' or not(response->>'replayed')::boolean then raise exception 'publish_retry';end if;tests:=array_append(tests,'publish_retry');
  document_a:=public.get_core_quote_version(company,quote_id,version_a);
  if document_a->'document'->>'customer_identity_state'<>'captured' or document_a->'document'->'customer'->>'billing_street'<>'Original street 1' then raise exception 'c02_captured_identity';end if;tests:=array_append(tests,'c02_captured_identity');
  begin perform public.update_core_quote_draft_atomic(company,quote_id,3,gen_random_uuid(),data);raise exception 'expected_closed';exception when sqlstate 'PT409' then if sqlerrm<>'CORE_QUOTE_DRAFT_CLOSED' then raise;end if;end;tests:=array_append(tests,'issued_projection_closed');
  begin perform public.convert_core_quote_to_job_atomic(company,quote_id,version_a,conversion_op,plan);raise exception 'expected_not_accepted';exception when sqlstate 'PT409' then if sqlerrm<>'CORE_QUOTE_STATUS_INVALID' then raise;end if;end;tests:=array_append(tests,'publication_not_acceptance');
  execute 'reset role';
  update public.customers set billing_street='Changed street 2',name='Changed customer' where id=customer;
  update public.companies set name='Changed supplier',logo_url='https://example.invalid/changed.png' where id=company;
  execute 'set local role anon';
  response:=public.get_public_core_quote_version(token_a);
  if response->'document'->'customer'<>jsonb_build_object('name','TEST original customer') or response::text like '%billing_street%' or response::text like '%NEVER PUBLIC%' then raise exception 'public_identity_redaction';end if;tests:=array_append(tests,'public_identity_redaction');
  if response->'document'->'supplier'<>document_a->'document'->'supplier' then raise exception 'supplier_snapshot_not_live';end if;tests:=array_append(tests,'supplier_snapshot_not_live');
  if(select count(*) from public.get_public_offer_items_by_token(token_a))<>1 or(select total_price from public.get_public_offer_by_token(token_a))<>8 then raise exception 'legacy_read_immutable_adapter';end if;tests:=array_append(tests,'legacy_read_immutable_adapter');
  previous:=response;
  public_input:=jsonb_build_object('version_id',version_a,'action_type','interested','note','Test interest only','visitor_id','test-visitor-a','user_agent','TEST initial browser','referrer','https://example.invalid/offer?source=A');
