  response:=public.respond_public_core_quote_version(token_a,response_op,public_input-array['user_agent','referrer']);
  if response-'replayed'<>public_first-'replayed' or not(response->>'replayed')::boolean then raise exception 'response_missing_transport_replays_original_receipt';end if;tests:=array_append(tests,'response_missing_transport_replays_original_receipt');
  execute 'reset role';
