  execute 'set local role anon';
  begin perform public.respond_public_core_quote_version(token_a,response_op,public_input||jsonb_build_object('visitor_id','test-visitor-b'));raise exception 'expected_visitor_conflict';exception when sqlstate 'PT409' then if sqlerrm<>'CORE_QUOTE_OPERATION_CONFLICT' then raise;end if;end;tests:=array_append(tests,'response_changed_visitor_conflicts');
  begin perform public.respond_public_core_quote_version(token_a,response_op,public_input||jsonb_build_object('action_type','not_interested'));raise exception 'expected_response_conflict';exception when sqlstate 'PT409' then null;end;tests:=array_append(tests,'response_changed_payload_conflict');
  begin perform public.respond_public_core_quote_version(token_a,gen_random_uuid(),jsonb_build_object('version_id',gen_random_uuid(),'action_type','interested'));raise exception 'expected_wrong_version';exception when sqlstate 'P0002' then null;end;tests:=array_append(tests,'response_wrong_version');
  if public.get_public_core_quote_version(token_a)->>'status'<>'published' then raise exception 'interest_not_acceptance';end if;tests:=array_append(tests,'interest_not_acceptance');
