  response:=public.record_core_quote_decision_atomic(company,quote_id,version_a,decision_op,jsonb_build_object('decision','accepted','evidence','TEST written approval, not an electronic signature','decided_at',to_char(clock_timestamp() at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"')));
  if response->>'revision'<>'4' or response->>'decisionId' is null then raise exception 'decision_audit_receipt';end if;tests:=array_append(tests,'decision_audit_receipt');
