  if not(response->>'created')::boolean or response->>'versionId'<>version_a::text then raise exception 'versioned_conversion';end if;tests:=array_append(tests,'versioned_conversion');
  previous:=response;response:=public.convert_core_quote_to_job_atomic(company,quote_id,version_a,conversion_op,plan);
  if(response->>'created')::boolean or response->>'jobId'<>previous->>'jobId' then raise exception 'conversion_retry_one_tree';end if;tests:=array_append(tests,'conversion_retry_one_tree');
  execute 'reset role';
  if(select count(*) from public.jobs where id=job_id or parent_job_id=job_id)<>2 or(select price from public.jobs where id=job_id)<>8 or(select source_quote_version_id from public.jobs where id=job_id)<>version_a then raise exception 'one_parent_one_day_price_version';end if;tests:=array_append(tests,'one_parent_one_day_price_version');
  set constraints all immediate;set constraints all deferred;
  execute 'set local role authenticated';
  response:=public.open_core_quote_revision_atomic(company,quote_id,version_a,4,gen_random_uuid());
  if response->>'revision'<>'5' then raise exception 'open_revision';end if;tests:=array_append(tests,'open_revision');
  data:=public.get_core_quote_workspace(company,quote_id)->'draft';data:=jsonb_set(data,'{items,0,unit_price}','"20.00"');
  perform public.update_core_quote_draft_atomic(company,quote_id,5,gen_random_uuid(),data);
  response:=public.publish_core_quote_version_atomic(company,quote_id,6,gen_random_uuid());version_b:=(response->>'versionId')::uuid;token_b:=response->>'shareToken';
  if response->>'versionNumber'<>'2' or version_b=version_a or token_b=token_a then raise exception 'new_version_new_token';end if;tests:=array_append(tests,'new_version_new_token');
  if public.get_core_quote_version(company,quote_id,version_a)->'document'<>document_a->'document' then raise exception 'accepted_version_immutable_after_b';end if;tests:=array_append(tests,'accepted_version_immutable_after_b');
  begin perform public.convert_core_quote_to_job_atomic(company,quote_id,version_b,gen_random_uuid(),plan);raise exception 'expected_version_conversion_conflict';exception when sqlstate 'PT409' then if sqlerrm<>'CORE_QUOTE_VERSION_CONFLICT' then raise;end if;end;tests:=array_append(tests,'new_version_no_old_job_alias');
